func (q *Queries) LockSchedule(ctx context.Context, arg LockScheduleParams) (int64, error) {
	row := q.db.QueryRow(ctx, lockSchedule, arg.OrgID, arg.PublicID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

