const lockScheduleTeam = `-- name: LockScheduleTeam :one
SELECT id, public_id, name, slug
FROM teams
WHERE org_id = $1 AND public_id = $2 AND deleted_at IS NULL
FOR NO KEY UPDATE
`

type LockScheduleTeamParams struct {
	OrgID    int64
	PublicID string
}

type LockScheduleTeamRow struct {
	ID       int64
	PublicID string
	Name     string
	Slug     string
}

// LockScheduleTeam locks a Team that is not deleted for a change of its Schedules, FOR NO KEY UPDATE: the changes of
// one Team's Schedules and the Team's deletion, which takes the same lock, run one after the other, so that the first
// Schedule is the main one and a Team with Schedules is never deleted.
func (q *Queries) LockScheduleTeam(ctx context.Context, arg LockScheduleTeamParams) (LockScheduleTeamRow, error) {
	row := q.db.QueryRow(ctx, lockScheduleTeam, arg.OrgID, arg.PublicID)
	var i LockScheduleTeamRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.Name,
		&i.Slug,
	)
	return i, err
}

